import * as z from "zod/v4";
import { registerContinuation, registerContinuationChannel, } from "../../internal/continuation-registration.js";
import { createResourceChannel } from "../../internal/resource-channel.js";
import { ISSUE_CREATED_EVENT_TYPE, } from "./types.js";
const issueResourceSchema = z
    .object({
    name: z.string().min(1),
    title: z.string().min(1),
    body: z.string().min(1),
    state: z.enum(["STATE_UNSPECIFIED", "STATE_OPEN", "STATE_CLOSED"]).optional(),
    createTime: z.string().min(1).optional(),
    updateTime: z.string().min(1).optional(),
    path: z.string().optional(),
    etag: z.string().optional(),
})
    .passthrough();
const issueCreatedEventSchema = z.object({
    eventId: z.string().min(1),
    eventType: z.literal(ISSUE_CREATED_EVENT_TYPE),
    teamId: z.string().min(1),
    occurredAtMs: z.number().int().nonnegative(),
    issue: issueResourceSchema,
});
const pack = createResourceChannel({
    kind: "issues",
    eventTypes: [ISSUE_CREATED_EVENT_TYPE],
    eventSchema: issueCreatedEventSchema,
    replayDescription: "Replay an issue-created event.",
    invalidError: "invalid issue event",
});
export function issuesChannel(options) {
    return pack.channel(options);
}
export function getIssuesChannelOptions(definition) {
    return pack.getOptions(definition);
}
registerContinuationChannel({
    kind: "issues",
    getOptions: getIssuesChannelOptions,
    usesDeclaredEvents: true,
});
registerContinuation({
    type: "factory-issue",
    kind: "issues",
    events: [ISSUE_CREATED_EVENT_TYPE],
    format: "issues:{issueName}",
    selector: "issues.issue/v2",
});
